import base64
import io
# Sons système intégrés en mémoire (zéro dépendance de dossier asset)
SOUND_MICRO_B64 = b""
SOUND_BIP_B64 = b""

def get_micro_sound_stream():
    """Retourne un flux BytesIO prêt pour soundfile.read()."""
    return io.BytesIO(base64.b64decode(SOUND_MICRO_B64))
def get_bip_sound_stream():
    """Retourne un flux BytesIO prêt pour soundfile.read()."""
    return io.BytesIO(base64.b64decode(SOUND_BIP_B64))
